        "van": {"name": "Van", "heightRange": "6'8\" and up", "length": "26+ feet"}
    }
}
""")

def recommend_car_size(customer_height):
  """Recommends a car size based on customer height and provided data."""
  for size, details in car_data["carSizes"].items():
    height_range = details["heightRange"].split(" - ")
    min_height, max_height = height_range[0], height_range[1]
    if customer_height >= min_height and customer_height <= max_height:
      return details["name"]  
  return "Van"  # Default to Van if no exact match found (handles heights exceeding chart)

# Get customer height input (ensure proper format handling in real application)
customer_height = input("Enter your height (e.g., '5'8\"'): ") 
recommended_size = recommend_car_size(customer_height)
print(f"Based on your height, we recommend a {recommended_size} car.") 
