        let clickedProduct = products.first { $0.id == mostClicked } ?? Product(id: "Unknown", dominantColor: .Neutral, reviewSentimentScore: 0)
        statement +=  " You frequently explored products like \(clickedProduct.id), known for their \(clickedProduct.dominantColor.description) aesthetic."
    }

